// Shared tenant-driven discovery contract.
// One workflow serves every tenant; NEVER clone per tenant.
// Inputs: tenant_id + brief_ref (Source Brief reference).

const input = $json;

if (!input.tenant_id || !input.brief_ref) {
  throw new Error('LOOM_DISCOVERY_INVALID: tenant_id and brief_ref are required');
}

const scope = {
  tenant_id: input.tenant_id,
  brief_ref: input.brief_ref,
  query: input.query || '',
  platform: input.platform || 'youtube'
};

// Discovery NEVER authorizes publication. This workflow only reaches the
// manual-ingest boundary; no download, no OpenShorts, no clip, no publish.
return [{ json: scope }];

// Route to manual-ingest boundary only. No auto download/process/publish.
// If the discovery call failed, hand off to the shared failure handler (LOOM-00).
const p = $json;
if (p && p.error) {
  return [{
    json: {
      failure_code: 'SOURCE_DISCOVERY_FAILED',
      stage: 'source-discovery',
      error_message: String(p.error).substring(0, 1000),
      tenant_id: p.tenant_id || 'unknown',
      retryable: false
    }
  }];
}
return [{ json: { status: 'manual_ingest_boundary', records: (p && p.records) || [], tenant_id: p && p.tenant_id } }];
